/* Life OS anchored desktop navigation: pane-local, not window-fixed.
   Keep native narrow-pane/mobile navigation and settings' inner scroller. */
@media (min-width: 861px) {
  .workspace-leaf-content > .view-content:has(> .lifeos-workspace:not(.lifeos-is-narrow-pane):not(.lifeos-is-mobile-runtime)) {
    height: 100% !important;
    min-height: 0 !important;
    overflow: hidden !important;
    padding: 0 !important;
  }
  .workspace-leaf-content > .view-content > .lifeos-root.lifeos-workspace:not(.lifeos-is-narrow-pane):not(.lifeos-is-mobile-runtime),
  .workspace-leaf-content > .view-content > .lifeos-root.lifeos-workspace:not(.lifeos-is-narrow-pane):not(.lifeos-is-mobile-runtime) > .lifeos-shell {
    height: 100% !important;
    min-height: 0 !important;
    max-height: 100% !important;
    overflow: hidden !important;
  }
  .workspace-leaf-content .lifeos-root.lifeos-workspace:not(.lifeos-is-narrow-pane):not(.lifeos-is-mobile-runtime) > .lifeos-shell {
    display: grid !important;
    grid-template-columns: 196px minmax(0, 1fr) !important;
    grid-template-rows: minmax(0, 1fr) !important;
    align-items: stretch !important;
  }
  .workspace-leaf-content .lifeos-root.lifeos-workspace:not(.lifeos-is-narrow-pane):not(.lifeos-is-mobile-runtime) > .lifeos-shell > .lifeos-sidebar {
    position: relative !important;
    inset: auto !important;
    width: auto !important;
    min-width: 0 !important;
    max-width: 100% !important;
    height: 100% !important;
    min-height: 0 !important;
    max-height: 100% !important;
    align-self: stretch !important;
    overflow-x: hidden !important;
    overflow-y: auto !important;
    overscroll-behavior-y: contain;
    scrollbar-width: thin;
    padding: 18px 12px !important;
    box-sizing: border-box !important;
  }
  .workspace-leaf-content .lifeos-root.lifeos-workspace:not(.lifeos-is-narrow-pane):not(.lifeos-is-mobile-runtime) > .lifeos-shell > .lifeos-main {
    height: 100% !important;
    min-height: 0 !important;
    max-height: 100% !important;
    overflow-y: auto !important;
    overscroll-behavior-y: contain;
    box-sizing: border-box !important;
    scrollbar-gutter: stable;
  }
  /* Settings already owns a bounded inner scroll area. */
  .workspace-leaf-content .lifeos-root.lifeos-workspace > .lifeos-shell > .lifeos-main.lifeos-settings-main {
    overflow: hidden !important;
  }
  .workspace-leaf-content .lifeos-workspace:not(.lifeos-is-narrow-pane):not(.lifeos-is-mobile-runtime) .lifeos-sidebar .lifeos-brand {
    padding: 4px 8px 14px !important;
    margin: 0 0 8px !important;
    flex-shrink: 0;
  }
  .workspace-leaf-content .lifeos-workspace:not(.lifeos-is-narrow-pane):not(.lifeos-is-mobile-runtime) .lifeos-sidebar .lifeos-nav-item {
    min-height: 36px !important;
    padding: 8px 10px !important;
    font-size: 13px !important;
    line-height: 20px !important;
    text-align: left !important;
    justify-content: flex-start !important;
  }
  .workspace-leaf-content .lifeos-workspace:not(.lifeos-is-narrow-pane):not(.lifeos-is-mobile-runtime) .lifeos-sidebar :is(.lifeos-sidebar-main, .lifeos-sidebar-footer) {
    flex: 0 0 auto !important;
  }
}

